// Exact disjoint lower-prime zero shard for Q4279.
// Includes the compiled/regression-validated release implementation so the
// recurrence, Montgomery arithmetic, and reflection materialization are
// literally identical to q4279_scan.cpp.

#define main q4279_embedded_scan_main
#include "q4279_scan.cpp"
#undef main

namespace {
struct ZOpt { u32 pmin=17,pmax=1000000,threads=0; std::string out="zero-shard"; };
ZOpt zopts(int ac,char**av){ZOpt o;for(int i=1;i<ac;++i){std::string a=av[i];auto need=[&](){if(++i>=ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--pmin")o.pmin=std::stoul(need());else if(a=="--pmax")o.pmax=std::stoul(need());else if(a=="--threads")o.threads=std::stoul(need());else if(a=="--out")o.out=need();else if(a=="-h"||a=="--help"){std::cout<<"q4279_zero_shard --pmin N --pmax N [--threads N] [--out DIR]\n";std::exit(0);}else throw std::runtime_error("unknown option "+a);}if(o.pmax<o.pmin)throw std::runtime_error("pmax<pmin");if(o.pmax>=20000000U)throw std::runtime_error("shard pmax must be <20000000");if(!o.threads)o.threads=std::max(1u,std::thread::hardware_concurrency());return o;}
}

int main(int ac,char**av){try{ZOpt o=zopts(ac,av);fs::create_directories(o.out);auto all0=std::chrono::steady_clock::now();Check ck=validate();auto pr=primes_to(o.pmax);std::size_t lo=std::lower_bound(pr.begin(),pr.end(),o.pmin)-pr.begin(),hi=std::upper_bound(pr.begin(),pr.end(),o.pmax)-pr.begin(),tasks=hi-lo;std::vector<std::vector<u32>>Z(tasks);std::atomic<std::size_t>cur{0},done{0};std::atomic<u64>steps{0},records{0};std::mutex pm;auto t0=std::chrono::steady_clock::now();auto work=[&](){u64 ls=0,lr=0;for(;;){std::size_t k=cur.fetch_add(1);if(k>=tasks)break;std::size_t i=tasks-1-k;u64 st=0;Z[i]=zeros_fast(pr[lo+i],&st);ls+=st;lr+=Z[i].size();std::size_t d=done.fetch_add(1)+1;if(d%2500==0||d==tasks){steps.fetch_add(ls);records.fetch_add(lr);ls=lr=0;std::lock_guard<std::mutex>g(pm);std::cerr<<"SHARD_PROGRESS "<<d<<'/'<<tasks<<" elapsed="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()<<"\n";}}steps.fetch_add(ls);records.fetch_add(lr);};std::vector<std::thread>th;for(u32 i=0;i<o.threads;++i)th.emplace_back(work);for(auto&t:th)t.join();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count();u64 refl=0,rf=0,cons=0,cf=0,ge3=0,ge4=0,maxz=0,maxp=0;std::ofstream zr(fs::path(o.out)/"zero_records.csv"),zc(fs::path(o.out)/"prime_zero_counts.csv");zr<<"p,r\n";zc<<"p,Z\n";for(std::size_t i=0;i<tasks;++i){u32 p=pr[lo+i];const auto&z=Z[i];zc<<p<<','<<z.size()<<'\n';if(z.size()>=3)++ge3;if(z.size()>=4)++ge4;if(z.size()>maxz){maxz=z.size();maxp=p;}for(u32 r:z){zr<<p<<','<<r<<'\n';++refl;if(!has(z,p-1-r))++rf;}for(std::size_t j=1;j<z.size();++j){++cons;if(z[j]==z[j-1]+1)++cf;}}if(rf||cf)throw std::runtime_error("shard reflection/consecutive failure");double total=std::chrono::duration<double>(std::chrono::steady_clock::now()-all0).count();std::ofstream m(fs::path(o.out)/"manifest.json");m<<std::setprecision(17)<<"{\n  \"pmin_requested\": "<<o.pmin<<",\n  \"pmax_requested\": "<<o.pmax<<",\n  \"first_prime\": "<<(tasks?pr[lo]:0)<<",\n  \"last_prime\": "<<(tasks?pr[hi-1]:0)<<",\n  \"prime_count\": "<<tasks<<",\n  \"zero_records\": "<<records.load()<<",\n  \"recurrence_steps\": \""<<steps.load()<<"\",\n  \"threads\": "<<o.threads<<",\n  \"zero_seconds\": "<<sec<<",\n  \"total_seconds\": "<<total<<",\n  \"steps_per_second\": "<<(sec?double(steps.load())/sec:0)<<",\n  \"primes_Z_ge_3\": "<<ge3<<",\n  \"primes_Z_ge_4\": "<<ge4<<",\n  \"max_Z\": "<<maxz<<",\n  \"max_Z_prime\": "<<maxp<<",\n  \"checks\": {\"release_selected_states_le_5000\": "<<ck.states<<", \"release_selected_leaves_le_5000\": "<<ck.leaves<<", \"release_candidate_mismatch\": "<<ck.cmis<<", \"reflection_checks\": "<<refl<<", \"reflection_failures\": "<<rf<<", \"consecutive_checks\": "<<cons<<", \"consecutive_failures\": "<<cf<<"}\n}\n";std::ofstream s(fs::path(o.out)/"summary.txt");s<<"Q4279_ZERO_SHARD pmin="<<o.pmin<<" pmax="<<o.pmax<<" primes="<<tasks<<" zeros="<<records.load()<<" steps="<<steps.load()<<" seconds="<<sec<<"\n";std::cout<<s.rdbuf();return 0;}catch(const std::exception&e){std::cerr<<"Q4279_ZERO_SHARD_FATAL "<<e.what()<<'\n';return 2;}}
